            std::mem::ManuallyDrop::drop(&mut self.root);
            std::mem::ManuallyDrop::drop(&mut self.reads);
            std::mem::ManuallyDrop::drop(&mut self.active_returned);
            std::mem::ManuallyDrop::drop(&mut self.active_root);
        }
    }
